(() => {
  'use strict';
  const c = window.CONTENT, $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
  const e = s => String(s ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
  const track = (event, data = {}) => { if(c.config.analyticsEnabled) { window.dataLayer = window.dataLayer || []; window.dataLayer.push({event,...data}); } window.dispatchEvent(new CustomEvent('gl:analytics',{detail:{event,...data}})); };
  const btn = (text, source, interest = '', secondary = false) => `<button class="button ${secondary?'secondary':''}" data-qualify="${e(source)}" data-interest="${e(interest)}">${e(text)} <span aria-hidden="true">↗</span></button>`;
  const photo = (label, img, extra = '') => img?.src ? `<figure class="photo ${extra}"><picture>${img.avif?`<source type="image/avif" srcset="${e(img.avif)}">`:''}${img.webp?`<source type="image/webp" srcset="${e(img.webp)}">`:''}<img src="${e(img.src)}" ${img.srcset?`srcset="${e(img.srcset)}"`:''} sizes="(max-width: 768px) 100vw, 50vw" alt="${e(img.alt || label)}" width="${img.width||1200}" height="${img.height||900}" loading="${extra==='hero-photo'?'eager':'lazy'}" ${extra==='hero-photo'?'fetchpriority="high"':''}></picture></figure>` : `<figure class="photo placeholder ${extra}" aria-label="${e(c.ui.photo)}"><div class="surface-light" aria-hidden="true"></div><figcaption><span class="photo-cross" aria-hidden="true">+</span>[ FOTO REAL — ${e(label)} ]</figcaption></figure>`;
  const heading = (data) => `<p class="eyebrow">${e(data.eyebrow)}</p><h2>${e(data.title)}</h2>`;
  const logo = () => c.brand.logo?`<img class="brand-logo" src="${e(c.brand.logo)}" alt="${e(c.brand.name)}">`:`<span class="wordmark">${e(c.brand.short)}<small>${e(c.brand.descriptor)}</small></span>`;
  const nav = () => c.nav.map(([id,t])=>`<a href="#${id}">${e(t)}</a>`).join('');
  const stars = `<span class="stars" aria-label="${e(c.ui.stars)}">★★★★★</span>`;
  const direct = (source) => `<a class="text-link" data-direct="${source}" target="_blank" rel="noopener" href="https://wa.me/${c.contact.whatsapp}?text=${encodeURIComponent(c.form.directMessage)}">${e(c.ui.direct)} ↗</a>`;
  const address = `${c.contact.street}, ${c.contact.district}, ${c.contact.city} - ${c.contact.state}, ${c.contact.zip}`;
  const map = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
  const insta = `https://www.instagram.com/${c.contact.instagram}/`;
  const options = values => `<option value="">${e(c.form.selectPlaceholder)}</option>` + values.map(t=>`<option>${e(t)}</option>`).join('');
  $('#app').innerHTML = `
    <a class="skip" href="#inicio">${e(c.ui.skip)}</a><div class="scroll-progress" aria-hidden="true"></div>
    <header class="header"><a class="brand" href="#inicio" aria-label="${e(c.brand.name)}">${logo()}</a><nav class="desktop-nav" aria-label="${e(c.ui.navigation)}">${nav()}</nav>${btn(c.ui.schedule,'header')}<button class="menu-toggle" aria-label="${e(c.ui.menu)}" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></header>
    <dialog id="mobile-menu" class="mobile-menu"><button class="close" data-close-menu aria-label="${e(c.ui.close)}">×</button><nav>${nav()}</nav>${btn(c.ui.schedule,'menu')}</dialog>
    <main><section class="hero" id="inicio"><div class="hero-grid"><div class="hero-copy"><p class="eyebrow">${e(c.hero.eyebrow)}</p><h1>${c.hero.lines.map((l,i)=>`<span class="line"><span class="${i===2?'metal-text':''}">${e(l)}</span></span>`).join('')}</h1><p class="hero-description">${e(c.hero.description)}</p><div class="actions">${btn(c.ui.primary,'hero')}<a class="text-link" href="#resultados">${e(c.ui.results)} <span>↘</span></a></div><div class="hero-rating">${stars}<strong>${e(c.rating.value)} ${e(c.rating.label)}</strong><span>${c.rating.count} ${e(c.rating.reviews)}</span></div></div><div class="hero-visual"><span class="visual-index">GL / 01</span>${photo('VEÍCULO FINALIZADO',c.hero.image,'hero-photo')}<div class="visual-caption"><span>${e(c.hero.visualLabel)}</span><span>${e(c.hero.caption)}</span></div></div></div><div class="hero-bottom"><span>${e(c.brand.tagline)}</span><a href="#identificacao">${e(c.ui.scroll)} ↓</a><span>${e(c.contact.city)} · ${e(c.contact.state)}</span></div></section>
    <div class="authority"><div>${stars} <b>${e(c.rating.value)} ${e(c.rating.label)}</b></div>${c.authority.map(t=>`<span>${e(t)}</span>`).join('')}</div>
    <section id="identificacao" class="section problem"><div>${heading(c.problem)}</div><div class="problem-copy"><p>${e(c.problem.text)}</p><div class="tags">${c.problem.tags.map(t=>`<span>${e(t)}</span>`).join('')}</div></div></section>
    <section class="section transformation" id="transformacao"><div class="section-heading">${heading(c.transformation)}<p>${e(c.transformation.text)}</p></div><div class="comparison"><div class="comparison-before">${photo('ANTES',c.transformation.beforeImage)}</div><div class="comparison-after">${photo('DEPOIS',c.transformation.afterImage)}</div><span class="compare-label before-label">${e(c.ui.before)}</span><span class="compare-label after-label">${e(c.ui.after)}</span><div class="compare-handle" aria-hidden="true"><span>↔</span></div><input id="comparison-range" type="range" min="0" max="100" value="50" aria-label="${e(c.ui.slider)}"></div><p class="caption">${e(c.ui.illustration)}</p><div class="transformation-stages">${c.transformation.stages.map((t,i)=>`<span><small>0${i+1}</small>${e(t)}</span>`).join('')}</div><div class="section-action">${btn(c.ui.primary,'transformation')}</div></section>
    <section id="servicos" class="section services">${heading(c.services)}${[...c.services.items,...c.services.other].map((s,i)=>`<article class="service service-${i}"><div class="service-visual">${photo(s.label,s.image)}</div><div class="service-copy"><p class="eyebrow">0${i+1} / ${e(s.label)}</p><h3>${e(s.title)}</h3><p>${e(s.text)}</p>${s.benefits?`<ul>${s.benefits.map(t=>`<li>${e(t)}</li>`).join('')}</ul>`:''}${btn(s.cta,'service_'+s.id,i===0?'Higienização':'Lavagem / cuidado',true)}</div></article>`).join('')}<div class="intermediate"><h3>${e(c.services.prompt)}</h3><div class="actions">${btn(c.services.known,'services')}${btn(c.services.recommendation,'recommendation','Ainda não sei',true)}</div></div></section>
    <section class="quality-wrap" id="qualidade"><div class="section quality">${heading(c.quality)}<div class="quality-grid"><div class="quality-photos">${c.quality.steps.map((s,i)=>`<div class="quality-photo ${i===0?'active':''}" data-step="${i}">${photo(s.photo,s.image)}</div>`).join('')}</div><div class="quality-steps">${c.quality.steps.map((s,i)=>`<article class="quality-step ${i===0?'active':''}"><span class="eyebrow">${e(c.ui.details)} 0${i+1}</span><h3>${e(s.title)}</h3><p>${e(s.text)}</p></article>`).join('')}</div></div></div></section>
    <section id="processo" class="section process">${heading(c.process)}<ol>${c.process.steps.map((t,i)=>`<li><span>0${i+1}</span><h3>${e(t)}</h3></li>`).join('')}</ol></section>
    <section class="section why"><div><p class="eyebrow">${e(c.brand.short)}</p><h2>${e(c.why.title)}</h2><p>${e(c.why.text)}</p><p class="aside">${e(c.why.aside)}</p></div>${photo(c.why.photo,null)}</section>
    <section id="resultados" class="section results">${heading(c.results)}<p>${e(c.results.text)}</p><div class="results-grid">${c.results.photos.map(x=>photo(x.label,x.image)).join('')}</div></section>
    <section id="avaliacoes" class="section testimonials"><div class="reviews-heading"><div>${heading(c.testimonials)}</div><div class="rating-block"><strong>${e(c.rating.value)}</strong>${stars}<span>${c.rating.count} ${e(c.rating.reviews)} · ${e(c.ui.google)}</span><small>${e(c.rating.note)}</small></div></div><div class="review-grid">${c.testimonials.items.map((r,i)=>`<article class="review" data-review="${i}">${stars}<blockquote>“${e(r.text).replace(/(impecável|0km novamente|produtos de 1ª linha|cuidado|qualidade)/gi,'<strong>$1</strong>')}”</blockquote><div class="review-author"><span class="avatar" aria-hidden="true">${e(r.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div><b>${e(r.name)}</b><small>${e(r.type?`${r.type} · Google`:'Google')}</small></div></div></article>`).join('')}</div><div class="section-action">${btn(c.ui.primary,'testimonials')}</div></section>
    <section class="emotion"><div class="emotion-inner">${c.emotion.words.map(t=>`<p>${e(t)}</p>`).join('')}<span>${e(c.emotion.caption)}</span></div></section>
    <section class="section funnel">${heading(c.funnel)}<p>${e(c.funnel.text)}</p><div class="actions">${btn(c.ui.primary,'funnel')}${direct('funnel')}</div></section>
    <section class="section final-cta">${photo('VEÍCULO FINALIZADO',c.cta.image)}<div><p class="eyebrow">${e(c.brand.tagline)}</p><h2>${e(c.cta.title)}</h2><p>${e(c.cta.text)}</p>${btn(c.cta.button,'final')}<small>${e(c.cta.micro)}</small></div></section>
    <section id="faq" class="section faq"><div>${heading(c.faq)}</div><div>${c.faq.items.map(([q,a],i)=>`<article class="faq-item"><h3><button aria-expanded="false" aria-controls="answer-${i}" id="question-${i}">${e(q)}<span aria-hidden="true">+</span></button></h3><div class="faq-answer" id="answer-${i}" role="region" aria-labelledby="question-${i}" hidden><p>${e(a)}</p></div></article>`).join('')}</div></section>
    <section id="contato" class="section contact"><div>${heading(c.location)}<address><b>${e(c.brand.name)}</b><br>${e(c.contact.street)}<br>${e(c.contact.district)} · ${e(c.contact.city)} – ${e(c.contact.state)}<br>${e(c.contact.zip)}</address><a class="phone" href="tel:+${c.contact.whatsapp}">${e(c.contact.phone)}</a><div class="hours">${c.contact.hours.map(t=>`<p>${e(t)}</p>`).join('')}</div><div class="actions">${btn(c.ui.schedule,'contact')}<a class="text-link" data-event="instagram_click" href="${insta}" target="_blank" rel="noopener">${e(c.ui.instagram)} ↗</a></div></div><div class="map-card"><span class="map-marker" aria-hidden="true">↗</span><p class="eyebrow">${e(c.contact.city)} / ${e(c.contact.state)}</p><h3>${e(c.location.mapLabel)}</h3><p>${e(c.contact.street)}</p><a class="button secondary" data-event="map_click" href="${map}" target="_blank" rel="noopener">${e(c.ui.map)} ↗</a>${c.contact.mapEmbedUrl?`<iframe loading="lazy" title="${e(c.location.directions)}" src="${e(c.contact.mapEmbedUrl)}" tabindex="-1"></iframe>`:''}</div></section>
    </main><footer class="section footer"><div class="footer-grid"><div><a class="brand" href="#inicio">${logo()}</a><p>${e(c.brand.tagline)}</p></div><div><h3>${e(c.ui.navigation)}</h3><a href="#inicio">${e(c.ui.home)}</a>${nav()}</div><div><h3>${e(c.ui.contact)}</h3><a href="tel:+${c.contact.whatsapp}">${e(c.contact.phone)}</a>${direct('footer')}<a data-event="instagram_click" href="${insta}" target="_blank" rel="noopener">@${e(c.contact.instagram)}</a><p>${e(address)}</p></div><div><h3>${e(c.ui.attendance)}</h3>${c.contact.hours.map(t=>`<p>${e(t)}</p>`).join('')}<a href="${map}" data-event="map_click" target="_blank" rel="noopener">${e(c.location.directions)} ↗</a><button class="text-link" data-qualify="footer">${e(c.cta.button)}</button></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${e(c.ui.rights)}</span><button data-legal="privacy">${e(c.ui.privacy)}</button><button data-legal="terms">${e(c.ui.terms)}</button><a href="https://www.instagram.com/fdss.dev_/" target="_blank" rel="noopener">${e(c.ui.footerCredit)} · @fdss.dev_ ↗</a></div></footer>
    <dialog id="qualification" class="modal"><button class="close" data-close aria-label="${e(c.ui.close)}">×</button><p class="eyebrow">${e(c.brand.short)}</p><h2>${e(c.form.title)}</h2><p>${e(c.form.intro)}</p><form id="lead-form"><div class="form-grid"><label>${e(c.form.labels[0])}<input name="name" autocomplete="name" required maxlength="100" placeholder="${e(c.form.namePlaceholder)}"></label><label>${e(c.form.labels[1])}<input name="vehicle" required maxlength="100" placeholder="${e(c.form.vehiclePlaceholder)}"></label><label>${e(c.form.labels[2])}<select name="service" required>${options(c.form.services)}</select></label><label>${e(c.form.labels[3])}<select name="condition" required>${options(c.form.conditions)}</select></label><label>${e(c.form.labels[4])}<select name="urgency" required>${options(c.form.urgencies)}</select></label><label>${e(c.form.labels[5])}<input name="phone" type="tel" autocomplete="tel" inputmode="tel" required maxlength="20" placeholder="${e(c.form.phonePlaceholder)}"></label></div><p class="form-notice">${e(c.form.notice)} <button type="button" data-legal="privacy">${e(c.ui.privacy)}</button></p><button class="button submit" type="submit">${e(c.ui.next)} ↗</button><div class="form-status" role="status" aria-live="polite"></div></form>${direct('form')}</dialog>
    <dialog id="legal" class="modal legal"><button class="close" data-close-legal aria-label="${e(c.ui.close)}">×</button><h2></h2><p></p></dialog>`;

  let source = '', completed = false, opener;
  const modal = $('#qualification'), menu = $('#mobile-menu');
  const lock = () => document.body.classList.toggle('locked',!!$('dialog[open]'));
  function closeMenu(){menu.close();$('.menu-toggle').setAttribute('aria-expanded','false');lock();}
  $('.menu-toggle').addEventListener('click',()=>{menu.showModal();$('.menu-toggle').setAttribute('aria-expanded','true');lock();if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.fromTo('#mobile-menu nav a',{y:20,opacity:0},{y:0,opacity:1,stagger:.05,duration:.3});});
  $('[data-close-menu]').onclick = closeMenu; menu.addEventListener('close',()=>{$('.menu-toggle').setAttribute('aria-expanded','false');lock();});
  $$('#mobile-menu a').forEach(a=>a.addEventListener('click',closeMenu));
  $$('[data-qualify]').forEach(b=>b.addEventListener('click',()=>{opener=b;if(menu.open)closeMenu();source=b.dataset.qualify;completed=false;$('#lead-form').reset();$('.form-status').replaceChildren();$('#lead-form [name=service]').value=b.dataset.interest||'';modal.showModal();lock();track('qualification_started',{source});if(source==='hero')track('hero_cta_click',{source});if(source.startsWith('service_'))track('service_click',{source});}));
  $('[data-close]').onclick=()=>modal.close();modal.addEventListener('close',()=>{if(!completed)track('qualification_abandoned',{source});lock();opener?.focus();});
  $$('dialog').forEach(d=>d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}}));
  $$('[data-direct]').forEach(a=>a.addEventListener('click',()=>track('whatsapp_direct_click',{source:a.dataset.direct})));
  $$('[data-event]').forEach(a=>a.addEventListener('click',()=>track(a.dataset.event,{source:a.closest('footer')?'footer':'contact'})));
  $$('[data-legal]').forEach(b=>b.addEventListener('click',()=>{const d=$('#legal');d.querySelector('h2').textContent=c.ui[b.dataset.legal];d.querySelector('p').textContent=c.legal[b.dataset.legal];d.showModal();lock();}));
  $('[data-close-legal]').onclick=()=>$('#legal').close();$('#legal').addEventListener('close',lock);
  const range=$('#comparison-range');range.addEventListener('input',()=>{$('.comparison').style.setProperty('--position',`${range.value}%`);range.setAttribute('aria-valuetext',`${range.value}% ${c.ui.before}`);});range.addEventListener('change',()=>track('before_after_interaction',{value:Number(range.value)}));
  $$('.faq-item button').forEach((b,i)=>b.addEventListener('click',()=>{const panel=$('#'+b.getAttribute('aria-controls')),open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.querySelector('span').textContent=open?'−':'+';panel.hidden=!open;if(open){track('faq_open',{index:i});if(window.gsap&&!matchMedia('(prefers-reduced-motion: reduce)').matches)gsap.fromTo(panel,{height:0,opacity:0},{height:'auto',opacity:1,duration:.25,clearProps:'height,opacity'});}}));
  const form=$('#lead-form'), phone=form.elements.phone;
  phone.addEventListener('input',()=>phone.setCustomValidity(''));
  form.addEventListener('change',event=>track('qualification_step',{source,field:event.target.name}));
  form.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));const digits=data.phone.replace(/\D/g,'');if(!/^(?:55)?\d{10,11}$/.test(digits)){phone.setCustomValidity(c.form.phoneError);phone.reportValidity();return;}
    const message=c.form.message.replace(/\{(\w+)\}/g,(_,key)=>data[key]||'');const url=`https://wa.me/${c.contact.whatsapp}?text=${encodeURIComponent(message)}`;
    const priority=data.urgency===c.form.urgencies[0]?'QUENTE':data.urgency===c.form.urgencies[3]?'PESQUISA':'MORNO';
    completed=true;track('qualification_completed',{source,priority});
    const status=$('.form-status');status.innerHTML=`<p>${e(c.form.success)}</p><a class="button" target="_blank" rel="noopener" href="${e(url)}">${e(c.form.fallback)} ↗</a>`;status.querySelector('a').onclick=()=>track('whatsapp_qualified_click',{source});
    // Start persistence without waiting: database latency cannot block the user's WhatsApp gesture.
    if(c.config.supabase.enabled&&c.config.supabase.url&&c.config.supabase.anonKey){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),4500);fetch(c.config.supabase.url.replace(/\/$/,'')+'/rest/v1/leads',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json',apikey:c.config.supabase.anonKey,Authorization:`Bearer ${c.config.supabase.anonKey}`,Prefer:'return=minimal'},body:JSON.stringify({name:data.name,phone:digits,vehicle:data.vehicle,service_interest:data.service,vehicle_condition:data.condition,urgency:data.urgency,source,status:'novo',priority})}).then(r=>{if(!r.ok)throw new Error('lead storage failed');}).catch(()=>track('lead_storage_unavailable',{source})).finally(()=>clearTimeout(timeout));}
    track('whatsapp_qualified_click',{source});window.open(url,'_blank','noopener');
  });
  const reviewObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){track('testimonial_view',{index:Number(entry.target.dataset.review)});reviewObserver.unobserve(entry.target);}}),{threshold:.4});$$('.review').forEach(el=>reviewObserver.observe(el));
  let ticking=false;const onScroll=()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.transform=`scaleX(${max?scrollY/max:0})`;$('.header').classList.toggle('scrolled',scrollY>30);ticking=false;});};addEventListener('scroll',onScroll,{passive:true});onScroll();
  const schema={'@context':'https://schema.org','@type':'AutomotiveBusiness',name:c.brand.name,telephone:'+'+c.contact.whatsapp,address:{'@type':'PostalAddress',streetAddress:c.contact.street,addressLocality:c.contact.city,addressRegion:c.contact.state,postalCode:c.contact.zip,addressCountry:'BR'},sameAs:[insta]};
  if(c.config.ratingVerified)schema.aggregateRating={'@type':'AggregateRating',ratingValue:5,reviewCount:c.rating.count};
  if(c.config.siteUrl){const base=c.config.siteUrl.replace(/\/$/,'');schema.url=base;const canonical=document.querySelector('link[rel=canonical]')||document.createElement('link');canonical.rel='canonical';canonical.href=base+'/';document.head.append(canonical);const og=document.querySelector('meta[property="og:url"]')||document.createElement('meta');og.setAttribute('property','og:url');og.content=base+'/';document.head.append(og);}
  const structured=document.querySelector('script[type="application/ld+json"]')||document.createElement('script');structured.type='application/ld+json';structured.textContent=JSON.stringify(schema);document.head.append(structured);
  if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'start_car_care_qualification',title:c.form.title,description:'Open the car-care qualification form. Does not send data or contact the business.',inputSchema:{type:'object',properties:{serviceInterest:{type:'string',enum:c.form.services}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='serviceInterest')||(input.serviceInterest!==undefined&&!c.form.services.includes(input.serviceInterest)))throw new Error('Invalid service interest');if(!modal.open)$('[data-qualify="funnel"]').click();if(input.serviceInterest)form.elements.service.value=input.serviceInterest;return{opened:modal.open,serviceInterest:form.elements.service.value};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
  window.initAnimations?.();
})();
